IF OBJECT_ID('dbo.price_audit','U') IS NOT NULL DROP TABLE dbo.price_audit; IF OBJECT_ID('dbo.price_rejection_log','U') IS NOT NULL DROP TABLE dbo.price_rejection_log; IF OBJECT_ID('dbo.product_price','U') IS NOT NULL DROP TABLE dbo.product_price;
CREATE TABLE dbo.product_price(ProductID int PRIMARY KEY,ProductName nvarchar(100),CostPrice decimal(10,2),Price decimal(10,2)); CREATE TABLE dbo.price_audit(AuditID int IDENTITY PRIMARY KEY,ProductID int,OldPrice decimal(10,2),NewPrice decimal(10,2),ChangedBy sysname,ChangedAt datetime2 DEFAULT SYSDATETIME()); CREATE TABLE dbo.price_rejection_log(RejectID int IDENTITY PRIMARY KEY,ProductID int,AttemptedPrice decimal(10,2),CostPrice decimal(10,2),AttemptedBy sysname,AttemptedAt datetime2 DEFAULT SYSDATETIME(),Reason nvarchar(200)); INSERT dbo.product_price VALUES(1,'Keyboard',500,850),(2,'Mouse',250,450),(3,'Monitor',6200,7500),(4,'Headset',800,1200),(5,'Webcam',1000,1500);